const $=(q,p=document)=>p.querySelector(q),$$=(q,p=document)=>[...p.querySelectorAll(q)],E=D.escapeHTML;
const app=$('#app');let catalog,chart,settings={},entries=[],csrf='',view={page:'home'},epoch=0,offline=false,scanBusy=false,cameraStream=null,scanTimer=null,lastScan=0,controller=null;
const historyViews=[];let historyIndex=-1,pendingScan=null;
const moveCache=new Map(),wikiCache=new Map(),pendingWiki=new Set(),pendingZa=new Set();
const glyphs={back:'M19 12H5m7-7-7 7 7 7',close:'m6 6 12 12M18 6 6 18',scan:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M9 12h6m-3-3v6',camera:'M8 5 9 3h6l1 2h4v15H4V5Z M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',image:'M3 3h18v18H3Z m0 14 6-6 5 5 4-4 3 4 M18 7h.01',search:'M15 15 21 21 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',collection:'M7 5h14v17H7Z M3 18V2h14 M18 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M10 13h8',stats:'M3 21h18 M5 16V9m7 7V3m7 13V6',settings:'M12 3v2m0 14v2M3 12h2m14 0h2M5.5 5.5 7 7m10 10 1.5 1.5M5.5 18.5 7 17m10-10 1.5-1.5 M18 12a6 6 0 1 1-12 0 6 6 0 0 1 12 0 M14 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0',speaker:'M3 9h4l5-5v16l-5-5H3Z M16 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',play:'m8 4 12 8-12 8Z',plus:'M12 4v16M4 12h16',history:'M21 12a9 9 0 1 1-9-9 M12 7v5l4 3 M16 3h5v5',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7m4-7v7',more:'M5 12h.01M12 12h.01M19 12h.01',heart:'M12 21 3 12C-3 4 7-1 12 6c5-7 15-2 9 6Z',download:'M12 3v12m-5-5 5 5 5-5 M3 17v4h18v-4',upload:'M12 17V5m-5 5 5-5 5 5 M3 17v4h18v-4',lock:'M6 10h12v12H6Z M8 10V6a4 4 0 0 1 8 0v4',normal:'M20 12a8 8 0 1 1-16 0 8 8 0 0 1 16 0',fire:'M12 2c2 6-4 7-1 11 2-1 4-3 4-5 7 10 2 14-3 14S1 17 5 10c0 4 2 5 3 5-2-6 4-7 4-13Z',water:'M12 2C9 7 4 11 4 15a8 8 0 0 0 16 0c0-4-5-8-8-13Z',electric:'M13 2 4 14h7l-1 8 10-13h-7Z',grass:'M20 3C5 1 1 8 4 17c7 7 16 1 16-14Z M4 20 16 8',ice:'M12 2v20M3 7l18 10M3 17 21 7 M9 4l3 3 3-3M9 20l3-3 3 3',fighting:'M5 12V7h3V5h3V4h3v2h3v2h3v9c-2 8-15 8-15-5Z',poison:'M12 3a9 9 0 0 0-6 16v3h12v-3a9 9 0 0 0-6-16Z M7 12h1m8 0h1M10 19h4',ground:'M3 21 9 3h7l5 18Z M7 21 12 8',flying:'M2 18C8 5 15 10 22 3c-1 13-12 17-20 15Z M6 16 17 11',psychic:'M20 12a8 8 0 1 1-8-8 6 6 0 1 1-6 6 4 4 0 1 1 4 4',bug:'M12 7v15 M8 4 5 1m11 3 3-3 M7 7C0 13 3 20 9 22V9m8-2c7 6 4 13-2 15V9',rock:'m3 19 4-14 10-2 5 12-7 7Z M7 5l5 10-9 4m9-4 5-12',ghost:'M3 20V11a9 9 0 0 1 18 0v11l-4-3-4 3-4-3Z M8 10h1m6 0h1',dragon:'M3 18 8 10 6 3l6 3 8-3-3 9 5 9H7Z M12 9h2 M8 16h7',dark:'M17 3a9 9 0 1 0 0 18 11 11 0 0 1 0-18Z',steel:'m6 3 12 0 5 9-5 9H6L1 12Z M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',fairy:'m12 1 3 7 7 4-7 3-3 8-3-8-8-3 8-4Z',stellar:'m12 2 2 7 8 3-8 2-2 8-2-8-8-2 8-3Z M4 3h.01M20 21h.01'};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${glyphs[name]||glyphs.normal}"/></svg>`;
const key=(name,label,action,extra='')=>`<button class="icon-btn ${extra}" aria-label="${E(label)}" title="${E(label)}" data-action="${E(action)}">${icon(name)}</button>`;
const primary=(label,action,name='')=>`<button class="primary-btn" data-action="${E(action)}">${name?icon(name):''}${E(label)}</button>`;
const pair=(label,value)=>`<div class="pair"><span>${E(label)}</span><span>${E(value??'—')}</span></div>`;
const note=v=>`<p class="note">${E(v)}</p>`;
const card=(label,content)=>`<section class="card"><h3 class="card-label">${E(label)}</h3>${content}</section>`;
const pill=(type,label='',action='type:'+type)=>`<button class="pill" style="--type:${D.COLORS[type]||D.COLORS.normal}" data-action="${E(action)}">${icon(type)}${E(label||D.TYPE_NAMES[type]||D.display(type))}</button>`;
const chips=(types,factors=false)=>`<div class="chips">${types.map(v=>typeof v==='string'?pill(v):pill(v.type,(D.TYPE_NAMES[v.type]||v.type)+(factors?' ×'+factor(v.multiplier):''))).join('')}</div>`;
const factor=v=>v===.25?'¼':v===.5?'½':v;
const art=url=>url?'/api/asset?url='+encodeURIComponent(url):'/assets/icon.svg';
const picture=(d,cls='')=>`<img class="${cls}" src="${E(art(d.artwork))}" alt="${E(d.name||'')}" loading="lazy" data-art>`;
const date=(v,full=true)=>v?new Date(v).toLocaleString('es-MX',full?{dateStyle:'medium',timeStyle:'short'}:{dateStyle:'medium'}):'—';
const metric=(value,label)=>`<div class="metric"><strong>${E(value)}</strong><small>${E(label)}</small></div>`;
const nav=page=>`<nav class="nav" aria-label="Navegación principal">${['home','collection','stats','settings'].map((p,i)=>`<button aria-label="${['Escáner','Colección','Estadísticas','Ajustes'][i]}" title="${['Escáner','Colección','Estadísticas','Ajustes'][i]}" ${p===page||page==='detail'&&p==='collection'||page==='camera'&&p==='home'?'aria-current="page"':''} data-action="nav:${p}">${icon(['scan','collection','stats','settings'][i])}</button>`).join('')}</nav>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function on(q,event,handler,root=document){$$(q,root).forEach(el=>el.addEventListener(event,e=>Promise.resolve(handler(e,el)).catch(err=>toast(err.message))));}

let idbPromise;
function db(){return idbPromise||(idbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('pokedex-web',1);req.onupgradeneeded=()=>req.result.createObjectStore('cache');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);}));}
async function cached(key,value){try{const database=await db();return await new Promise((resolve,reject)=>{const txn=database.transaction('cache',value===undefined?'readonly':'readwrite'),req=value===undefined?txn.objectStore('cache').get(key):txn.objectStore('cache').put(value,key);let result;req.onsuccess=()=>{result=req.result;};txn.oncomplete=()=>resolve(result);txn.onerror=()=>reject(txn.error);});}catch{return undefined;}}
async function clearCache(){try{const database=await db();await new Promise(r=>{const txn=database.transaction('cache','readwrite');txn.objectStore('cache').clear();txn.oncomplete=r;});}catch{}if('caches'in window)for(const k of await caches.keys())if(k.startsWith('pokedex-'))await caches.delete(k);}
async function api(path,body,options={}){
 const method=options.method||(body===undefined?'GET':'POST');let response,value;
 const cacheable=method==='GET'&&path!=='/api/export'&&!path.startsWith('/api/scan-jobs/');
 try{const result=await request(path,{method,headers:{...(body===undefined?{}:{'Content-Type':'application/json'}),...(method==='GET'?{}:{'X-Pokedex-CSRF':csrf})},body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin'},{timeout:options.binary?90000:path==='/api/dex'||path.startsWith('/api/dex?')?60000:12000,...options,retries:path==='/api/bootstrap'?1:0});response=result.response;value=result.data;}
 catch(err){if(err.connection&&cacheable&&options.allowOffline!==false){const old=await cached('get:'+path);if(old!==undefined){offline=true;showOffline();return path==='/api/bootstrap'?{...old,csrf:''}:old;}}throw err;}
 if(!response.ok){if(response.status===401&&value.auth&&path!=='/api/login'){await clearCache();entries=[];csrf='';go({page:'login'},true);}const error=Error(value.error||'No se pudo completar la solicitud.');error.status=response.status;throw error;}
 if(cacheable)await cached('get:'+path,value);offline=false;showOffline();return value;
}
function showOffline(){const old=$('.offline');if(offline&&!old){const badge=document.createElement('div');badge.className='offline';badge.textContent='Sin conexión · datos guardados';document.body.append(badge);}else if(!offline&&old)old.remove();}
async function refresh(allowOffline=true){const value=await api('/api/bootstrap',undefined,{allowOffline});csrf=value.csrf;settings=value.settings;entries=value.encounters;return value;}
const audio={
 ctx:null,node:null,generation:0,
 configure(){try{if(navigator.audioSession)navigator.audioSession.type='playback';}catch{}},
 async resume(){
  this.configure();
  if(!this.ctx||this.ctx.state==='closed')throw Error('Toca Voz o Probar voz para activar el audio.');
  if(this.ctx.state==='running')return;
  let timer;try{await Promise.race([this.ctx.resume(),new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('El audio está bloqueado. Toca Voz o Probar voz para activarlo.')),3000);})]);}
  finally{clearTimeout(timer);}
  if(this.ctx.state!=='running')throw Error('No se pudo activar el audio. Cierra y vuelve a abrir Pokédex.');
 },
 async unlock(){
  this.configure();
  if(!this.ctx||this.ctx.state==='closed'){const C=window.AudioContext||window.webkitAudioContext;if(!C)throw Error('Este navegador no permite reproducir el audio.');this.ctx=new C();}
  const resumed=this.resume();
  // Start inside the tap, before awaiting settings or network requests on iOS.
  const silent=this.ctx.createBufferSource();silent.buffer=this.ctx.createBuffer(1,128,this.ctx.sampleRate);silent.connect(this.ctx.destination);silent.onended=()=>silent.disconnect();silent.start();
  await resumed;
 },
 stop(){this.generation++;if(this.node){try{this.node.stop();this.node.disconnect();}catch{}this.node=null;}},
 async play(bytes,robot=true,speed=1.12,token=this.generation){
  if(token!==this.generation)return false;
  await this.resume();const decoded=await this.ctx.decodeAudioData(bytes.slice(0));
  if(token!==this.generation)return false;
  // Opening the camera or returning from another app can interrupt iOS audio.
  await this.resume();if(token!==this.generation)return false;
  const buffer=this.ctx.createBuffer(decoded.numberOfChannels,decoded.length,decoded.sampleRate);
  for(let c=0;c<decoded.numberOfChannels;c++)buffer.copyToChannel(robot?D.roboticFilter(decoded.getChannelData(c),decoded.sampleRate):decoded.getChannelData(c),c);
  const source=this.ctx.createBufferSource();source.buffer=buffer;source.playbackRate.value=speed;source.connect(this.ctx.destination);this.node=source;
  source.onended=()=>{source.disconnect();if(this.node===source)this.node=null;};source.start();return true;
 }
};
async function speak(dex,automatic=false){if(!automatic)await audio.unlock();audio.stop();const token=audio.generation,pageToken=epoch;const body={lookup:D.slug(dex),species:dex.id,transformation:D.kind(dex),teraType:dex.teraType||'',game:view.game||settings.game||'scarlet-violet'};const cacheKey='voice:'+JSON.stringify({...body,voice:settings.voice||'Charon'});try{toast('Preparando la voz…');let bytes=await cached(cacheKey);if(!bytes){bytes=await api('/api/voice',body,{binary:true});await cached(cacheKey,bytes);}if(pageToken!==epoch||token!==audio.generation||document.hidden)return;if(await audio.play(bytes,settings.robot!==false,1.12,token))toast('Reproduciendo voz…');}catch(err){if(pageToken===epoch&&token===audio.generation)toast(err.message);}}
function stopCamera(){clearTimeout(scanTimer);scanTimer=null;controller?.abort();controller=null;cameraStream?.getTracks().forEach(track=>track.stop());cameraStream=null;scanBusy=false;}
function go(next,replace=false,scanned=false){stopCamera();audio.stop();closeSheet();epoch++;view=next;const index=replace&&historyIndex>=0?historyIndex:++historyIndex;historyViews.splice(index);historyViews[index]=view;if(replace)history.replaceState({pokedex:index},'');else history.pushState({pokedex:index},'');render();window.scrollTo(0,next.scroll||0);if(scanned&&settings.autoVoice!==false){const token=epoch;setTimeout(()=>{if(token===epoch)speak(view.dex,true);},120);}}
function back(){if(historyIndex>0)history.back();else go({page:'home'},true);}
window.addEventListener('popstate',event=>{const i=event.state?.pokedex;if(i!==undefined&&historyViews[i]){stopCamera();audio.stop();closeSheet();epoch++;historyIndex=i;view=historyViews[i];render();window.scrollTo(0,view.scroll||0);}else go({page:'home'},true);});
window.addEventListener('scroll',()=>{view.scroll=window.scrollY;},{passive:true});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopCamera();audio.stop();epoch++;if(view.page==='camera')$('#camera-status')?.replaceChildren(document.createTextNode('Escaneo pausado'));}});
function rerender(){const y=window.scrollY;render();window.scrollTo(0,y);}
function render(){document.documentElement.style.setProperty('--accent',view.page==='detail'?D.COLORS[D.typesFor(view.dex,view.game,catalog)[0]]||D.COLORS.normal:'#269fa3');document.querySelector('meta[name=theme-color]').content=view.page==='home'?'#c92a42':'#fafafa';if(view.page==='login')renderLogin();else if(view.page==='home')renderHome();else if(view.page==='camera')renderCamera();else if(view.page==='collection')renderCollection();else if(view.page==='stats')renderStats();else if(view.page==='settings')renderSettings();else if(view.page==='history')renderHistory();else if(view.page==='learners')renderLearners();else renderDetail();showOffline();bindArtwork();}
function bindArtwork(){on('[data-art]','error',(_,img)=>{if(!img.dataset.failed){img.dataset.failed='1';img.src='/assets/icon.svg';}});}
function renderLogin(){app.innerHTML=`<main class="login"><img class="login-logo" src="/assets/icon.svg" alt=""><h1>Pokédex</h1><form id="login"><input class="field" type="password" id="password" autocomplete="current-password" placeholder="Contraseña" aria-label="Contraseña" required><button class="primary-btn" type="submit">Entrar</button><p id="login-error" class="error-text" role="alert"></p></form><small class="center">Tu colección en Umbrel</small></main>`;on('#login','submit',async e=>{e.preventDefault();const button=$('#login button');button.disabled=true;try{const result=await api('/api/login',{password:$('#password').value});csrf=result.csrf;await refresh();go({page:'home'},true);}catch(err){$('#login-error').textContent=err.message;}finally{if(button.isConnected)button.disabled=false;}});}
function renderHome(){app.innerHTML=`<main class="ash"><div class="ash-head" aria-label="Pokédex roja de Ash"><div class="blue-lens"></div><div class="leds"><i></i><i></i><i></i></div><strong>POKÉDEX</strong></div><section class="ash-screen"><div class="home-content"><h1>¿Quién es ese Pokémon?</h1><div class="camera-actions"><button class="camera-main" aria-label="Abrir cámara" data-action="camera">${icon('camera')}</button>${key('image','Elegir imagen','gallery','gallery-btn')}</div><form id="search" class="home-search"><input class="field" id="query" aria-label="Nombre o número" placeholder="Nombre o número" autocomplete="off" enterkeyhint="search" required><button class="icon-btn primary" aria-label="Buscar" type="submit">${icon('search')}</button></form></div></section>${nav('home')}</main>`;on('#search','submit',e=>{e.preventDefault();return openLookup($('#query').value);});}
async function openLookup(query){const token=epoch;toast('Consultando ficha…');const d=await api('/api/dex?q='+encodeURIComponent(query));if(token!==epoch||document.hidden)return;openDetail(d);}
function openDetail(d,scanned=false){go({page:'detail',dex:d,game:settings.game||'scarlet-violet',tab:'about',method:'level-up',query:'',sort:'level',desc:false,statMode:'base',level:100},false,scanned);}
function renderCollection(){const filter=view.type||'';app.innerHTML=`<main class="page"><div class="topline">${filter?key('back','Volver','back'):''}<h2 class="title">${filter?E(D.TYPE_NAMES[filter]):'Colección'}</h2>${key('history','Registros','history')}</div><input class="field" id="collection-query" aria-label="Buscar en colección" placeholder="Nombre o número" value="${E(view.query||'')}"><div class="space"></div><div id="pokemon-grid" class="grid"></div></main>${nav('collection')}`;updateGrid();on('#collection-query','input',(_,input)=>{view.query=input.value;updateGrid();});}
function tile(entry,action){const d=entry.dex,t=d.types?.[0]||'normal';return `<button class="pokemon-tile" data-action="${E(action)}" style="--tile:color-mix(in srgb,${D.COLORS[t]||D.COLORS.normal} 18%,white)">${picture(d,'art')}<strong>${E(d.name)}</strong>${D.formLabel(d)?`<span class="form-label">${E(D.formLabel(d))}</span>`:''}<small>#${String(d.id).padStart(4,'0')} · ${D.count(entries,d.id)} ${D.count(entries,d.id)===1?'encuentro':'encuentros'}</small></button>`;}
function updateGrid(){const target=$('#pokemon-grid');if(!target)return;const rows=D.collection(entries,view.query||'',view.type||'');target.innerHTML=rows.map(e=>tile(e,'entry:'+e.id)).join('')||'<p class="empty">Todavía no hay registros que coincidan.</p>';if(!rows.length)target.classList.remove('grid');else target.classList.add('grid');bindArtwork();}
function renderStats(){const summary=D.statsSummary(entries),mode=view.mode||'types';const values=Object.entries(summary[mode]).sort((a,b)=>b[1]-a[1]);const maximum=Math.max(1,...values.map(v=>v[1]));app.innerHTML=`<main class="page"><div class="topline"><h2 class="title">Estadísticas</h2>${key('history','Registros','history')}</div><div class="summary-grid">${[['Pokémon',summary.unique],['Encuentros',summary.total],['Días',summary.days],['Favoritos',settings.favorites?.filter(id=>entries.some(e=>e.species===id)).length||0]].map(([name,value])=>`<div class="summary-number"><strong>${value}</strong><small>${name}</small></div>`).join('')}</div>${card('Exploración',`<div class="segmented"><button aria-pressed="${mode==='types'}" data-action="stats:types">Tipos</button><button aria-pressed="${mode==='species'}" data-action="stats:species">Pokémon</button></div><div class="bars">${values.map(([name,count])=>{const label=mode==='types'?D.TYPE_NAMES[name]:entries.find(e=>String(e.species)===name)?.dex.name;return `<button class="bar-row" data-action="${mode==='types'?'type:'+name:'species:'+name}" style="--accent:${mode==='types'?D.COLORS[name]:'#269fa3'}"><span>${E(label)}</span><span class="track" style="--fill:${count/maximum*100}%"><i></i></span><strong>${count}</strong></button>`;}).join('')||'<p class="empty">Escanea tu primer Pokémon.</p>'}</div>${note('Un Pokémon de dos tipos cuenta en ambas categorías.')}`)}${card('Fechas',pair('Primera vez',date(summary.first,false))+pair('Última vez',date(summary.last,false)))}</main>${nav('stats')}`;}
function renderHistory(){const rows=entries.filter(e=>!view.species||e.species===view.species);app.innerHTML=`<main class="page"><div class="topline">${key('back','Volver','back')}<h2 class="title">Registros</h2></div><div>${rows.map(e=>`<div class="history-row">${picture(e.dex)}<button class="grow" data-action="encounter-options:${e.id}"><strong>${E(e.dex.name)}</strong>${D.formLabel(e.dex)?`<small>${E(D.formLabel(e.dex))}</small>`:''}<small>${E(date(e.at))} · ${E(D.display(e.media))}</small></button>${key('trash','Eliminar este registro','delete:'+e.id,'danger')}</div>`).join('')||'<p class="empty">No hay registros.</p>'}</div></main>${nav('stats')}`;}
function gender(d){const r=d.genderRate;if(r<0||r===undefined)return metric('—','Sin género');const female=r*12.5,male=100-female;return `<div class="metric"><svg class="gender-ring" viewBox="0 0 42 42" aria-hidden="true"><circle cx="21" cy="21" r="15.9" fill="none" stroke="#4b88f5" stroke-width="8"/><circle cx="21" cy="21" r="15.9" fill="none" stroke="#f66b98" stroke-width="8" stroke-dasharray="${female} ${male}"/></svg><small>♂ ${male}% · ♀ ${female}%</small></div>`;}
function renderDetail(){const d=view.dex,types=D.typesFor(d,view.game,catalog),accent=D.COLORS[types[0]]||D.COLORS.normal;document.documentElement.style.setProperty('--accent',accent);app.innerHTML=`<main class="detail"><header class="hero"><div class="hero-bar">${key('back','Volver','back')}<div class="row">${key('heart',settings.favorites?.includes(d.id)?'Quitar favorito':'Añadir favorito','favorite')}${key('more','Opciones','detail-options')}</div></div><small>#${String(d.id).padStart(4,'0')} · Nacional</small><h1>${E(d.name)}</h1>${D.formLabel(d)?`<p class="form-label">${E(D.formLabel(d))}</p>`:''}${chips(types)}${picture(d)}</header><select class="game-switch" id="game" aria-label="Videojuego">${Object.entries(catalog.games).sort((a,b)=>b[1].order-a[1].order).map(([key,g])=>`<option value="${key}" ${view.game===key?'selected':''}>${E(g.name)}</option>`).join('')}</select><nav class="tabs" role="tablist" aria-label="Información de Pokémon">${[['about','Ficha'],['stats','Stats'],['moves','Movimientos'],['other','Otros']].map(([key,name])=>`<button role="tab" aria-selected="${view.tab===key}" data-action="tab:${key}">${name}</button>`).join('')}</nav><div class="detail-content" role="tabpanel" id="detail-content">${view.tab==='about'?aboutContent():view.tab==='stats'?statsContent():view.tab==='moves'?movesContent():extrasContent()}</div></main>${nav('detail')}`;on('#game','change',(_,input)=>{view.game=input.value;settings.game=input.value;view.query='';view.method='level-up';view.scroll=0;api('/api/settings',{game:input.value}).catch(e=>toast(e.message));rerender();});if(view.tab==='about')loadWiki(d);if(view.tab==='moves'){bindMoveInputs();ensureZa(d);}if(view.tab==='stats')on('#stat-level','change',(_,el)=>{view.level=Math.max(1,Math.min(100,parseInt(el.value)||100));rerender();});}
function aboutContent(){const d=view.dex,gen=catalog.games[view.game].generation,types=D.typesFor(d,view.game,catalog),description=D.description(d,view.game,catalog),weak=D.defenses(chart,types,gen).filter(t=>t.multiplier>1);let content=card('Especie',`<h3 class="center muted">${E(d.genus)}</h3><div class="space"></div><p>${E(description.text)}</p>${!description.exact?note('Entrada general · '+(catalog.versions[d.version]||D.display(d.version))):''}<div class="space"></div>${chips(types)}${weak.length?`<div class="space"></div><p class="center muted"><small>${D.kind(d)==='terastal'?'Debilidades originales':'Debilidades'}</small></p><div class="space"></div>${chips(weak,true)}`:''}<div class="metrics">${metric(Number(d.height).toFixed(1)+' m','Altura')}${gender(d)}${metric(Number(d.weight).toFixed(1)+' kg','Peso')}</div><div class="audio-actions"><button data-action="voice">${icon('speaker')}Voz</button>${d.cry?`<button data-action="cry">${icon('play')}Sonido</button>`:''}</div><div class="audio-actions"><button data-action="register">${icon('plus')}Registrar</button><button data-action="history-species">${icon('history')}${D.count(entries,d.id)} ${D.count(entries,d.id)===1?'encuentro':'encuentros'}</button></div>`);
 if(D.formLabel(d)){content+=card('Forma observada',pair('Forma',D.formLabel(d))+pair('Encuentros',entries.filter(e=>e.species===d.id&&D.formKey(e.dex)===D.formKey(d)).length)+(d.teraType?chips([d.teraType]):'')+(['terastal','dynamax'].includes(D.kind(d))?note(D.kind(d)==='terastal'?'Teratipo registrado. Imagen, tipos, estadísticas y debilidades corresponden a la forma original.':'Dinamax registrado. Los datos e imagen son originales; los PS no incluyen el aumento de Dinamax.'):''));}
 let abilities=d.abilities||[];const slots=new Map();for(const old of [...(d.pastAbilities||[])].sort((a,b)=>D.generation(b.generation)-D.generation(a.generation)))if(gen<=D.generation(old.generation))for(const a of old.abilities||[])slots.set(a.slot,a.ability);abilities=abilities.map(a=>({...a,name:slots.has(a.slot)?slots.get(a.slot)?.name:a.name})).filter(a=>a.name);
 content+=card('Habilidades',gen<3||view.game.startsWith('legends-')||view.game==='mega-dimension'||view.game.startsWith('lets-go')?note('Este juego no utiliza habilidades.'):abilities.map(a=>{const v=catalog.abilities[a.name]||{name:D.display(a.name)},text=D.preferred(v.texts,view.game,catalog);return `<h3>${E(v.name)}${a.hidden?' · oculta':''}</h3><p class="note">${E(text.text||'Descripción no disponible.')}${text.language==='9'?' (inglés)':''}</p><div class="space"></div>`;}).join(''));
 const rate=d.captureRate;content+=card('Captura',pair('Ratio base',rate<0?'—':rate+' / 255')+`<div class="capture-balls">${[['Poké Ball',1,'#dd644a'],['Super Ball',1.5,'#4380cc'],['Ultra Ball',2,'#d3b43e']].map(([n,mod,color])=>`<div class="ball-example"><strong>${rate<0?'—':'≈ '+(Math.floor(rate*mod/3)/255*100).toFixed(1)+'%'}</strong><span class="pokeball" style="--ball:${color}"></span><small>${n}</small></div>`).join('')}</div>`+note('Ejemplo de generaciones III–IV: PS completos y sin estado. El ratio base no es un porcentaje; no predice la captura en '+catalog.games[view.game].name+'.'));
 const growth={slow:'Lento',medium:'Medio',fast:'Rápido','medium-slow':'Parabólico','slow-then-very-fast':'Errático','fast-then-very-slow':'Fluctuante'};content+=card('Entrenamiento',pair('Crecimiento',growth[d.growthRate?.name]||'—')+pair('EV que otorga',(d.stats||[]).filter(s=>s.effort>0).map(s=>s.effort+' '+D.STAT_NAMES[s.name]).join('\n')||'—')+pair('Experiencia base',d.baseExperience)+pair('Amistad base',d.baseFriendship)+note('Valores actuales de referencia de la fuente; pueden variar por juego.'));
 const egg={monster:'Monstruo',water1:'Agua 1',bug:'Bicho',flying:'Volador',ground:'Campo',fairy:'Hada',plant:'Planta',humanshape:'Humanoide',water3:'Agua 3',mineral:'Mineral',indeterminate:'Amorfo',water2:'Agua 2',ditto:'Ditto',dragon:'Dragón','no-eggs':'No descubierto'};content+=card('Crianza',pair('Grupos huevo',(d.eggGroups||[]).map(v=>egg[v.name]||D.display(v.name)).join(' / '))+pair('Ciclos de eclosión',d.hatchCounter)+note('≈ '+(d.hatchCounter>=0?d.hatchCounter*255:'—')+' pasos como referencia clásica. Los pasos efectivos y la disponibilidad de crianza dependen del juego.'));
 content+=evolutionsContent()+formsContent()+wikiContent();return content;
}
function evolutionsContent(){const d=view.dex,list=d.evolutions||[];if(!list.length)return card('Evoluciones',note('La cadena aún no está disponible en la fuente.'));const depths=[...new Set(list.map(e=>e.depth))].sort((a,b)=>a-b);return card('Evoluciones',`<div class="evolution-tree">${depths.map(depth=>`<div class="evolution-column">${list.filter(e=>e.depth===depth).map(e=>{const current=e.id===d.id,seen=entries.find(v=>v.species===e.id)?.dex,unlocked=current||!!seen,shown=current?d:seen||e;return `<button class="evolution-tile" ${!unlocked||current?'disabled':''} data-action="evolution:${e.id}">${picture({...shown,name:unlocked?shown.name:'Pokémon sin registrar'},unlocked?'':'locked')}<strong>${unlocked?E(shown.name):'???'}</strong>${unlocked?(e.conditions||[]).map(c=>`<small>${E(D.evolutionText(c,catalog))}</small>`).join(''):''}</button>`;}).join('')}</div>`).join('')}</div>${note('Cadena general de la especie. Las condiciones pueden variar entre juegos.')}`);}
function formsContent(){const d=view.dex,seen=D.observed(entries,d.id).filter(f=>D.formKey(f)!==D.formKey(d)),all=new Map();for(const f of seen)all.set(D.formKey(f),f);for(const f of [...(d.varieties||[]),...(d.cosmeticForms||[])]){const k=f.name+'||';if(k===D.formKey(d)||all.has(k))continue;all.set(k,{name:'???',id:d.id,pokemonSlug:f.name,slug:d.slug,artwork:f.artwork||d.artwork||'',unseen:true});}if(!all.size)return '';view.forms=[...all.values()];return card('Formas alternativas',`<div class="grid">${view.forms.map((f,i)=>`<button class="evolution-tile" ${f.unseen?'disabled':''} data-action="form:${i}">${picture({...f,name:f.unseen?'Forma sin registrar':f.name},f.unseen?'locked':'')}<strong>${f.unseen?'???':E(D.formLabel(f)||f.name)}</strong></button>`).join('')}</div>`);}
function wikiContent(){const data=wikiCache.get(view.dex.name);return ['biology','etymology'].map((field,i)=>card(['Biología','Etimología'][i],`<div class="prose" data-wiki="${field}">${data?wikiText(data,field):note('Cargando WikiDex…')}</div>`)).join('');}
function wikiText(data,field){if(data.error)return `<p class="note">${E(data.error)}</p><button class="secondary-btn" data-action="retry-wiki">Reintentar</button>`;const prose=data[field]||'No disponible en la fuente.',first=prose.slice(0,500);return `<p>${E(first)}${prose.length>500?'…':''}</p>${prose.length>500?`<details><summary>Mostrar más</summary><p>${E(prose.slice(500))}</p></details>`:''}<div class="source-links"><a href="${E(data.source)}" target="_blank" rel="noopener noreferrer">WikiDex · colaboradores · CC BY-SA</a></div>`;}
async function loadWiki(d){if(wikiCache.has(d.name)||pendingWiki.has(d.name))return;pendingWiki.add(d.name);try{wikiCache.set(d.name,await api('/api/wiki?name='+encodeURIComponent(d.name)));}catch(e){wikiCache.set(d.name,{error:e.message});}finally{pendingWiki.delete(d.name);if(view.page==='detail'&&view.dex.name===d.name&&view.tab==='about')for(const field of ['biology','etymology']){const el=$(`[data-wiki="${field}"]`);if(el)el.innerHTML=wikiText(wikiCache.get(d.name),field);}}}
function defensesContent(rows,title='Defensas por tipo',attack=false){const labels=attack?{4:'Muy eficaz',2:'Eficaz',.25:'Muy poco eficaz',.5:'Poco eficaz',0:'Sin efecto',1:'Daño normal'}:{4:'Muy débil',2:'Débil',.25:'Muy resistente',.5:'Resistente',0:'Inmune',1:'Daño normal'};return card(title,[4,2,.25,.5,0,1].map(n=>{const group=rows.filter(t=>t.multiplier===n);return group.length?`<h3>${labels[n]} · ×${factor(n)}</h3><div class="space"></div>${chips(group)}<div class="space"></div>`:'';}).join('')+note(attack?'Ataque contra un solo tipo defensor. Dos tipos, habilidades y objetos pueden cambiar el resultado.':'Combinación de tipos según generación. No incluye habilidades, objetos ni teracristalización.'));}
function statsContent(){const d=view.dex,rows=D.statsFor(d,view.game,catalog),standard=!['champions','legends-arceus','lets-go-pikachu-lets-go-eevee'].includes(view.game),mode=standard?(view.statMode||'base'):'base',maximum=mode==='base'?255:714,gen=catalog.games[view.game].generation;return card('Estadísticas',`${!standard?note('Se muestran las estadísticas base. El cálculo de mínimos y máximos de este juego aún no está disponible.') :''}<div class="segmented">${(standard?[['base','Base'],['min','Mín.'],['max','Máx.']]:[['base','Base']]).map(([k,l])=>`<button aria-pressed="${mode===k}" data-action="statmode:${k}">${l}</button>`).join('')}</div>${mode!=='base'?`<label for="stat-level">Nivel</label><input class="field" id="stat-level" type="number" min="1" max="100" inputmode="numeric" value="${view.level}"><div class="space"></div>`:''}<div class="stat-bars">${rows.map(s=>{const v=D.stat(s.value,view.level,mode,s.name==='hp',gen);return `<div class="bar-row"><span>${E(D.STAT_NAMES[s.name]||s.name)}</span><div class="track" style="--fill:${Math.min(100,v/maximum*100)}%"><i></i></div><strong>${v}</strong></div>`;}).join('')}</div>${mode==='base'?pair('Total',rows.reduce((sum,s)=>sum+s.value,0)):note(gen<3?(mode==='min'?'DV 0 y experiencia de estadísticas 0. Estas generaciones no tienen naturalezas.':'DV 15 y experiencia de estadísticas al máximo, sin naturalezas.'):mode==='min'?'IV 0, EV 0 y naturaleza desfavorable. PS no depende de la naturaleza.':'IV 31, EV 252 y naturaleza favorable. Son máximos individuales; no pueden alcanzarse todos a la vez (límite total 510 EV).')}`)+defensesContent(D.defenses(chart,D.typesFor(d,view.game,catalog),catalog.games[view.game].generation),D.kind(d)==='terastal'?'Defensas originales':'Defensas por tipo');}
function moveRows(){if(view.game==='legends-za')return D.slug(view.dex)===view.dex.slug?(moveCache.get(view.dex.name)||[]):[];return D.movesFor(view.dex,view.game,catalog);}
function movesContent(){const rows=moveRows();if(view.game==='legends-za'&&!moveCache.has(view.dex.name)&&D.slug(view.dex)===view.dex.slug)return card('Movimientos',note('Consultando movimientos de Z-A…'));if(!rows.length)return card('Movimientos',note('La fuente no tiene movimientos de esta forma en '+catalog.games[view.game].name+'. No se mezclan otros juegos.'));const methods=[...new Set(['level-up','machine','egg','tutor',...rows.map(m=>m.method)])];return card('Movimientos',`<div class="segmented">${methods.map(k=>`<button aria-pressed="${view.method===k}" data-action="method:${E(k)}">${E(D.METHODS[k]||D.display(k))}</button>`).join('')}</div><input class="field" id="move-query" aria-label="Buscar movimiento" placeholder="Buscar movimiento" value="${E(view.query||'')}"><table class="move-table"><thead><tr>${[['display','Nombre'],['level',view.method==='machine'?'MT':'Nv.'],['power','Pot.'],[view.game==='legends-za'?'mastery':'accuracy',view.game==='legends-za'?'Dom.':'Prec.'],[view.game==='legends-za'?'cooldown':'pp',view.game==='legends-za'?'CD':'PP']].map(([field,name])=>`<th><button data-action="sort:${field==='level'&&view.method==='machine'?'machine':field}">${name}</button></th>`).join('')}</tr></thead><tbody id="move-rows">${moveTableRows()}</tbody></table>${note(view.game==='legends-za'?'Dom.: nivel de dominio. CD: recarga base en segundos. Aprendizaje: WikiDex (CC BY-SA). Potencia y recarga: Pokémon Project.':'Niveles y MT del juego seleccionado. Toca el ataque para consultar su efecto y tus Pokémon compatibles.')}`);}
const valueOrDash=v=>v===null||v===undefined||v<0?'—':v;
function moveTableRows(){const filtered=D.filterMoves(moveRows(),view.method,view.query,view.sort,view.desc);return filtered.map(m=>`<tr><td><button class="move-name" data-action="move:${E(m.name)}">${E(m.display||m.name)}<span class="move-type"><span class="type-dot" style="--type:${D.COLORS[m.type]||D.COLORS.normal}">${icon(m.type)}</span>${E(m.category||'')}<span>${E(m.descriptionGame!==view.game?'':'')}</span></span></button></td><td>${E(view.method==='machine'?m.machine||'—':valueOrDash(m.level))}</td><td>${E(valueOrDash(m.power))}</td><td>${E(valueOrDash(view.game==='legends-za'?m.mastery:m.accuracy))}</td><td>${E(valueOrDash(view.game==='legends-za'?m.cooldown:m.pp))}</td></tr>`).join('')||'<tr><td colspan="5"><p class="empty">Sin coincidencias.</p></td></tr>';}
function bindMoveInputs(){on('#move-query','input',(_,input)=>{view.query=input.value;$('#move-rows').innerHTML=moveTableRows();});}
async function ensureZa(d){if(view.game!=='legends-za'||D.slug(d)!==d.slug||moveCache.has(d.name)||pendingZa.has(d.name))return;pendingZa.add(d.name);try{moveCache.set(d.name,await api('/api/za-moves?name='+encodeURIComponent(d.name)));}catch(e){moveCache.set(d.name,[]);toast(e.message);}finally{pendingZa.delete(d.name);if(view.page==='detail'&&view.dex.id===d.id&&view.tab==='moves'&&view.game==='legends-za')rerender();}}
function extrasContent(){const d=view.dex;return card('Pokédex regionales',(d.pokedexNumbers||[]).map(p=>pair(D.display(p.pokedex?.name), '#'+p.entry_number)).join(''))+card('Nombres',(d.names||[]).map(n=>pair(({es:'Español',en:'Inglés',ja:'Japonés',fr:'Francés',de:'Alemán',ko:'Coreano','zh-Hans':'Chino simplificado','zh-Hant':'Chino tradicional'})[n.language.name]||n.language.name,n.name)).join(''))+card('Datos',pair('Generación',D.generation({name:d.generation}))+pair('Legendario',d.legendary?'Sí':'No')+pair('Mítico',d.mythical?'Sí':'No')+pair('Forma',D.formLabel(d)||'Original'))+card('Fuentes',`<p class="note">PokéAPI · datos de especies y formas. WikiDex · biología, etimología y aprendizaje de Z-A. Pokémon Project · potencia y recarga de Z-A.</p><div class="source-links"><a href="https://pokeapi.co/docs/v2" target="_blank" rel="noopener noreferrer">PokéAPI</a><a href="https://www.wikidex.net/wiki/WikiDex:Copyrights" target="_blank" rel="noopener noreferrer">WikiDex · CC BY-SA</a><a href="https://pkproject.net/leyendas-pokemon-z-a/movimientos-disponibles" target="_blank" rel="noopener noreferrer">Pokémon Project</a></div>`);}
function closeSheet(){for(const dialog of $$('dialog')){dialog.close();dialog.remove();}}
function sheet(title,content,footer='',accent=null){closeSheet();const el=document.createElement('dialog');el.className='dialog sheet';if(accent)el.style.setProperty('--accent',accent);el.innerHTML=`<header class="sheet-head"><div class="handle" aria-hidden="true"></div>${key('close','Cerrar ventana','close-sheet','sheet-close')}</header><div class="sheet-scroll">${title?`<h2 class="sheet-title">${E(title)}</h2>`:''}${content}</div><footer class="sheet-footer">${footer||'<button class="secondary-btn" data-action="close-sheet">Cerrar</button>'}</footer>`;document.body.append(el);el.showModal();el.addEventListener('cancel',()=>el.remove());el.addEventListener('click',e=>{if(e.target===el){const r=el.getBoundingClientRect();if(e.clientY<r.top||e.clientX<r.left||e.clientX>r.right)closeSheet();}});let start;$('.handle',el).addEventListener('pointerdown',e=>{start=e.clientY;e.target.setPointerCapture(e.pointerId);});$('.handle',el).addEventListener('pointerup',e=>{if(start!==undefined&&e.clientY-start>45)closeSheet();start=undefined;});bindArtwork();return el;}
function choose(title,options){const el=sheet(title,`<div class="choices">${options.map((o,i)=>`<button class="choice" data-choice="${i}">${E(o.label)}</button>`).join('')}</div>`);on('[data-choice]','click',(_,b)=>{closeSheet();return options[Number(b.dataset.choice)].run();},el);return el;}
function chooseTera(callback){choose('Teratipo',[...D.TYPES.map(t=>({label:D.TYPE_NAMES[t],run:()=>callback(t)})),{label:'No lo sé',run:()=>callback('')}]);}
function selectedPayload(d=view.dex){return {lookup:D.slug(d),species:d.id,transformation:D.kind(d),teraType:d.teraType||''};}
function confirmRegister(d=view.dex){const token=epoch;const el=sheet('Registrar encuentro',`<p class="center">${E(d.name)}${D.formLabel(d)?' · '+E(D.formLabel(d)):''}</p>`,`<div class="stack">${primary('Registrar','confirm-register','plus')}<button class="secondary-btn" data-action="choose-form">Elegir forma</button></div>`);on('[data-action="confirm-register"]','click',async(_,b)=>{b.disabled=true;const entry=await api('/api/encounters',{...selectedPayload(d),id:D.encounterId(),media:'otro'});if(token!==epoch)return;entries.unshift(entry);await cached('get:/api/bootstrap',{settings,encounters:entries,csrf});closeSheet();openDetail(entry.dex);toast('Encuentro registrado.');},el);on('[data-action="choose-form"]','click',()=>chooseForm(d),el);}
function chooseForm(d){const slugs=[...new Set([d.slug,D.slug(d),...(d.varieties||[]).map(f=>f.name),...(d.cosmeticForms||[]).map(f=>f.name)])];const token=epoch;const get=async(slug,kind='none')=>{const base=await api('/api/dex?q='+encodeURIComponent(slug));if(epoch!==token)return;if(kind==='terastal')chooseTera(t=>confirmRegister(D.applyForm(base,kind,t)));else confirmRegister(D.applyForm(base,kind));};const base=['mega','gigantamax'].includes(D.kind(d))?d.slug:D.slug(d);choose('Forma del encuentro',[...slugs.map(s=>({label:D.display(s),run:()=>get(s)})),{label:'Dinamax',run:()=>get(base,'dynamax')},{label:'Teracristalizado',run:()=>get(base,'terastal')}]);}
function showMove(name){const row=moveRows().find(r=>r.name===name)||D.moveInfo(name,view.game,catalog);view.lastMove=name;const za=view.game==='legends-za';const m=za?row:{...D.moveInfo(name,view.game,catalog),...row};const content=`<p class="sheet-eyebrow">MOVIMIENTO</p><h2 class="sheet-title">${E(m.display||m.name)}</h2><div class="chips">${pill(m.type)}<span class="pill" style="--type:#909399">${E(m.category||'—')}</span></div>${card('Estadísticas',`<div class="metrics">${metric(valueOrDash(m.power),'Potencia')}${metric(valueOrDash(za?m.cooldown:m.accuracy),za?'Recarga (s)':'Precisión')}${metric(valueOrDash(za?m.mastery:m.pp),za?'Dominio':'PP')}</div>`)}${card('Detalles',`<h3>Descripción</h3><div class="space"></div><p>${E(m.description||'Descripción no disponible para este juego.')}${m.language==='9'?' (inglés)':''}</p>${m.descriptionGame&&m.descriptionGame!==view.game?note('Descripción: '+catalog.games[m.descriptionGame]?.name):''}${!za&&m.effect?`<div class="space"></div><h3>Efecto</h3><div class="space"></div><p>${E(m.effect.replaceAll('$effect_chance',String(m.effectChance??'')))}</p>${note('Efecto de referencia de la fuente; puede estar en inglés.')}`:''}${m.contest?`<div class="space"></div>${pair('Concurso',({Cool:'Carisma',Beauty:'Belleza',Cute:'Dulzura',Smart:'Ingenio',Tough:'Dureza'})[m.contest]||D.display(m.contest))}`:''}${pair('Prioridad',valueOrDash(m.priority))}${pair('Aprendizaje',D.METHODS[m.method]||'—')}${pair(m.method==='machine'?'MT':'Nivel',m.method==='machine'?m.machine||'—':valueOrDash(m.level))}`)}${defensesContent(D.attacking(chart,m.type,catalog.games[view.game].generation),m.category==='Estado'?'Afinidad del tipo':'Daño por tipo',true)}${m.category==='Estado'?note('Este movimiento de estado no causa daño. La tabla muestra solo la afinidad de su tipo.'):''}`;sheet('',content,primary('Pokémon registrados','learners','collection'),D.COLORS[m.type]||D.COLORS.normal);}
async function showLearners(){const move=view.lastMove,game=view.game,origin=view;go({page:'learners',move,game,origin,query:'',ready:[],pending:0,loading:true});const token=epoch,seen=new Set();for(const entry of entries){if(token!==epoch||document.hidden)return;const saved=entry.dex,key=D.slug(saved);if(seen.has(key))continue;seen.add(key);try{let d=await api('/api/dex?q='+encodeURIComponent(key));if(token!==epoch)return;d=D.applyForm(d,D.kind(saved),saved.teraType||'');let knows;if(game==='legends-za'){if(D.slug(d)!==d.slug){view.pending++;continue;}const moves=moveCache.get(d.name)||await api('/api/za-moves?name='+encodeURIComponent(d.name));if(token!==epoch)return;moveCache.set(d.name,moves);knows=moves.some(m=>m.name===move);if(!moves.length)view.pending++;}else{knows=D.knows(d,move,game);if(!d.learnset?.some(m=>m.game===game))view.pending++;}if(token!==epoch)return;if(knows&&!view.ready.some(v=>v.species===entry.species))view.ready.push({...entry,dex:d});}catch{if(token===epoch)view.pending++;}}if(token===epoch){view.loading=false;renderLearners();bindArtwork();}}
function renderLearners(){const m=D.moveInfo(view.move,view.game,catalog);app.innerHTML=`<main class="page"><div class="topline">${key('back','Volver al movimiento','back-move')}<div class="title"><h2>${E(m.display)}</h2><small>${E(catalog.games[view.game].name)}</small></div></div><input class="field" id="learner-query" aria-label="Buscar entre compatibles" placeholder="Buscar entre tus Pokémon" value="${E(view.query)}"><div class="space"></div><p class="note" id="learner-status"></p><div class="space"></div><div id="learner-grid" class="grid"></div>${view.pending?`<div class="space"></div><button class="secondary-btn" data-action="retry-learners">Volver a comprobar</button>`:''}</main>${nav('collection')}`;updateLearners();on('#learner-query','input',(_,el)=>{view.query=el.value;updateLearners();});}
function updateLearners(){const filtered=D.collection((view.ready||[]).filter(e=>entries.some(v=>v.species===e.species&&D.slug(v.dex)===D.slug(e.dex))),view.query||'');$('#learner-status').textContent=view.loading?'Consultando tus Pokémon…':filtered.length+(filtered.length===1?' registrado compatible':' registrados compatibles')+(view.pending?' · '+view.pending+' sin datos comprobables':'');$('#learner-grid').innerHTML=filtered.map(e=>tile(e,'learner:'+e.id)).join('')||(!view.loading?'<p class="empty">No hay coincidencias comprobadas en este juego.</p>':'');bindArtwork();}
function recognitionSettings(){const connected=settings.chatgpt?.connected;return card('Reconocimiento',`<label for="provider">Servicio</label><select id="provider" class="field"><option value="chatgpt" ${settings.provider==='chatgpt'?'selected':''}>ChatGPT Plus · mi suscripción</option><option value="openrouter" ${settings.provider==='openrouter'?'selected':''}>OpenRouter · modelos gratuitos</option><option value="gemini" ${settings.provider==='gemini'?'selected':''}>Gemini</option></select><div id="provider-key" class="${settings.provider==='chatgpt'?'hide':''}"><div class="space"></div><label for="recognition-key">Clave</label><input type="password" id="recognition-key" class="field" autocomplete="off" placeholder="Clave guardada"><p class="note">La clave vacía conserva la guardada. OpenRouter utiliza modelos gratuitos.</p></div><div id="chatgpt-settings" class="${settings.provider!=='chatgpt'?'hide':''}"><div class="space"></div>${connected?`<p class="note">Usando el plan de ChatGPT · ${E(settings.chatgpt.email)}</p><label for="chatgpt-model">Modelo</label><select id="chatgpt-model" class="field">${(settings.chatgptModels||[]).map(m=>`<option value="${E(m.slug)}" ${m.slug===settings.chatgpt.model?'selected':''}>${E(m.name)}</option>`).join('')}</select><div class="space"></div><button type="button" class="secondary-btn" data-action="chatgpt-models">Actualizar modelos</button><div class="space"></div><button type="button" class="secondary-btn" data-action="chatgpt-disconnect">Desconectar ChatGPT</button>`:`<button type="button" class="secondary-btn" data-action="chatgpt-setup">Continuar con ChatGPT</button>`}<div class="space"></div><button type="button" class="secondary-btn" data-action="chatgpt-import">Importar conexión de la computadora</button><input id="chatgpt-file" type="file" class="hide" accept="application/json,.json">${note('La primera conexión se autoriza desde la computadora. Después, Umbrel la conserva para el iPhone. Se aplican los límites de tu suscripción; no se utiliza una API de pago.')}<a href="https://chatgpt.com/#settings" target="_blank" rel="noopener noreferrer">Gestionar uso en ChatGPT</a></div><div class="space"></div><button type="button" class="secondary-btn" data-action="check-recognition">Comprobar acceso</button>`);}
function chatgptSetup(){sheet('Continuar con ChatGPT',`<p>Autoriza una vez desde esta computadora con el asistente incluido en el proyecto de Pokédex. El inicio de sesión se abre en el navegador interno de Codex.</p>${note('Después importa aquí el archivo de conexión. Se guarda de forma privada en Umbrel y no se incluye en las copias de la colección. No envíes ese archivo por chat.')}<p><a href="https://developers.openai.com/siwc/token-sharing-open-source/self-hosted-vms" target="_blank" rel="noopener noreferrer">Por qué se necesita la computadora</a></p>`);}
async function importChatGPT(el){const file=el.files[0];if(!file)return;try{if(!window.isSecureContext||location.protocol!=='https:')throw Error('Usa HTTPS de confianza para importar la conexión.');if(file.size>150000)throw Error('El archivo de conexión es demasiado grande.');let record;try{record=JSON.parse(await file.text());}catch{throw Error('Selecciona el archivo JSON creado por el asistente de Pokédex.');}toast('Verificando conexión…');settings=await api('/api/chatgpt/import',record,{timeout:45000});await api('/api/chatgpt/models',{}, {timeout:45000});await refresh(false);rerender();toast('ChatGPT conectado. Ya puedes escanear.');}finally{el.value='';}}
async function checkConnection(){const start=Date.now();const result=await api('/api/bootstrap',undefined,{allowOffline:false});csrf=result.csrf;settings=result.settings;entries=result.encounters;sheet('Conexión con Pokédex',pair('Dirección',location.origin)+pair('Respuesta',Date.now()-start+' ms')+pair('Cámara en vivo',window.isSecureContext&&navigator.mediaDevices?.getUserMedia?'Disponible':'Requiere HTTPS de confianza')+pair('Registros en Umbrel',entries.length)+note('Esta comprobación no envía imágenes ni consume reconocimiento.'));}
function renderSettings(){app.innerHTML=`<main class="page"><div class="topline"><h2>Ajustes</h2></div><form id="settings-form">${recognitionSettings()}${card('Narración · Gemini',`<label for="voice-key">Clave de voz</label><input type="password" class="field" id="voice-key" autocomplete="off" placeholder="${settings.hasVoice?'Clave guardada':'Clave de Gemini'}"><div class="space"></div><label for="voice-name">Voz</label><select id="voice-name" class="field">${[['Charon','Charon · informativa'],['Kore','Kore · firme'],['Puck','Puck · animada']].map(([v,n])=>`<option value="${v}" ${settings.voice===v?'selected':''}>${n}</option>`).join('')}</select><div class="toggle-row"><label for="auto-voice">Leer al identificar un Pokémon</label><input type="checkbox" id="auto-voice" ${settings.autoVoice!==false?'checked':''}></div><div class="toggle-row"><label for="robot">Voz robótica</label><input type="checkbox" id="robot" ${settings.robot!==false?'checked':''}></div><div class="audio-actions"><button type="button" data-action="check-voice">Comprobar acceso</button><button type="button" data-action="test-voice">Probar voz</button></div>${note('Voz 12 % más rápida. Sin tope diario de reconocimiento en Pokédex; se aplican las cuotas de cada proveedor. Voz: 40 narraciones nuevas al día. El audio guardado no consume otra solicitud.')}`)}<div class="space"></div><button class="primary-btn" type="submit">Guardar</button></form>${card('Colección',`<div class="stack">${primary('Exportar copia','export','download')}<button class="secondary-btn" data-action="import">Importar copia de Android o web</button><input class="hide" id="import-file" type="file" accept="application/json,.json">${note('El historial se guarda en Umbrel. Las claves no se incluyen en la copia. Android se transfiere mediante exportación e importación; todavía no se sincroniza automáticamente.')}</div>`)}${card('iPhone',`<div class="stack"><button class="secondary-btn" data-action="connection">Comprobar conexión</button><button class="secondary-btn" data-action="install-help">Añadir a pantalla de inicio</button><button class="secondary-btn" data-action="password">Cambiar contraseña</button><button class="secondary-btn" data-action="clear-keys">Eliminar claves guardadas</button><button class="secondary-btn" data-action="logout">Cerrar sesión</button></div>`)}<p class="note center">Pokédex Web · 1.3.0 · Umbrel</p></main>${nav('settings')}`;on('#settings-form','submit',saveSettings);on('#provider','change',(_,el)=>{$('#recognition-key').value='';$('#recognition-key').placeholder=(el.value==='gemini'?settings.hasGemini:settings.hasOpenrouter)?'Clave guardada':'Clave del servicio';$('#provider-key').classList.toggle('hide',el.value==='chatgpt');$('#chatgpt-settings').classList.toggle('hide',el.value!=='chatgpt');});on('#chatgpt-file','change',(_,el)=>importChatGPT(el));on('#import-file','change',(_,el)=>importFile(el));}
async function saveSettings(e,quiet=false){e?.preventDefault();const provider=$('#provider').value,body={provider,voice:$('#voice-name').value,robot:$('#robot').checked,autoVoice:$('#auto-voice').checked};const visionKey=$('#recognition-key').value.trim(),voiceKey=$('#voice-key').value.trim();if(visionKey&&provider!=='chatgpt')body[provider+'_key']=visionKey;const model=$('#chatgpt-model')?.value;if(provider==='chatgpt'&&model)body.chatgptModel=model;if(voiceKey)body.voice_key=voiceKey;settings=await api('/api/settings',body);$('#recognition-key').value='';$('#voice-key').value='';if(!quiet)toast('Ajustes guardados.');}
async function importFile(el){const file=el.files[0];if(!file)return;if(file.size>25*1024*1024)throw Error('La copia supera los 25 MB.');let parsed;try{parsed=JSON.parse(await file.text());}catch{throw Error('El archivo no es una copia JSON válida.');}const token=epoch;const result=await api('/api/import',parsed);await refresh();if(token===epoch)toast(result.inserted+' registros importados.');el.value='';}
async function exportFile(){const backup=await api('/api/export');const url=URL.createObjectURL(new Blob([JSON.stringify(backup,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='Pokedex-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function cameraStatus(message){const el=$('#camera-status');if(el)el.textContent=message;}
function renderCamera(){const photo=view.cameraMode==='photo';app.innerHTML=`<main class="camera-page"><div class="camera-view">${photo?`<button class="photo-prompt" data-action="photo" aria-label="Tomar foto">${icon('camera')}<span>Tomar foto</span></button>`:`<video id="camera" muted autoplay playsinline></video><div class="reticle" aria-hidden="true"></div>`}</div><p class="camera-status" id="camera-status" role="status">${photo?'':'Preparando cámara…'}</p><div class="camera-controls">${key('back','Volver','back')}${key(photo?'camera':'scan',photo?'Tomar foto':'Escanear ahora',photo?'photo':'capture','primary')}${key('image','Elegir imagen','gallery')}</div></main>${nav('home')}`;}
async function openCamera(){
 if(pendingScan){await audio.unlock().catch(e=>toast(e.message));sheet('Análisis pendiente',note('Hay un resultado pendiente. Consúltalo antes de enviar otra imagen.'),primary('Consultar resultado','resume-scan'));return;}
 if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia){go({page:'camera',cameraMode:'photo'});chooseImage(true);return;}
 await audio.unlock().catch(e=>toast(e.message));go({page:'camera'});const token=epoch;
 try{cameraStream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:960}}});if(token!==epoch||document.hidden){stopCamera();return;}$('#camera').srcObject=cameraStream;await $('#camera').play();cameraStatus('Buscando…');scheduleScan(token,3500);}catch(err){if(token===epoch){stopCamera();view.cameraMode='photo';renderCamera();cameraStatus(err.name==='NotAllowedError'?'Puedes tomar una foto o elegir una imagen.':'Toma una foto para identificarlo.');}}
}
function scheduleScan(token,delay){clearTimeout(scanTimer);scanTimer=setTimeout(()=>{scanTimer=null;if(token===epoch&&view.page==='camera'&&!document.hidden)capture().catch(e=>{cameraStatus(e.message);toast(e.message);});},delay);}
async function capture(){if(scanBusy||!cameraStream||document.hidden)return;const video=$('#camera');if(!video?.videoWidth){cameraStatus('Preparando cámara…');scheduleScan(epoch,500);return;}const delay=20000-(Date.now()-lastScan);if(lastScan&&delay>0){cameraStatus('Espera '+Math.ceil(delay/1000)+' s · el análisis empezará automáticamente.');scheduleScan(epoch,delay);return;}const canvas=document.createElement('canvas');const scale=Math.min(1,1024/video.videoWidth);canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);await analyze(canvas.toDataURL('image/jpeg',.8).split(',')[1]);}
function chooseImage(camera=false){audio.unlock().catch(e=>toast(e.message));closeSheet();stopCamera();let input=$('#gallery-file');if(!input){input=document.createElement('input');input.id='gallery-file';input.className='hide';input.type='file';input.accept='image/*';document.body.append(input);input.addEventListener('change',async()=>{const file=input.files[0];if(!file)return;const token=epoch;try{if(file.size>30*1024*1024)throw Error('Elige una imagen de menos de 30 MB.');const image=new Image();const url=URL.createObjectURL(file);try{image.src=url;await image.decode();if(token!==epoch)return;const canvas=document.createElement('canvas'),scale=Math.min(1,1024/Math.max(image.naturalWidth,image.naturalHeight));canvas.width=Math.round(image.naturalWidth*scale);canvas.height=Math.round(image.naturalHeight*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);await analyze(canvas.toDataURL('image/jpeg',.8).split(',')[1]);}finally{URL.revokeObjectURL(url);}}catch(e){toast(e.message);}finally{input.value='';}});}if(camera)input.setAttribute('capture','environment');else input.removeAttribute('capture');input.click();}
async function scanJob(operation,input,signal){const job={id:D.encounterId(),operation};pendingScan=job;try{await api('/api/scan-jobs',{id:job.id,operation,input},{signal});const result=await pollJob(job.id,path=>api(path,undefined,{allowOffline:false,signal}),{signal,progress:cameraStatus});pendingScan=null;return result;}catch(err){if(!err.connection&&!err.job&&err.name!=='AbortError')pendingScan=null;throw err;}}
async function resumeScan(){if(!pendingScan||scanBusy)return;scanBusy=true;controller=new AbortController();const token=epoch,job=pendingScan;try{const result=await pollJob(job.id,path=>api(path,undefined,{allowOffline:false,signal:controller.signal}),{signal:controller.signal,progress:cameraStatus});pendingScan=null;if(token!==epoch)return;if(job.operation==='encounters'){entries=entries.filter(e=>e.id!==result.id);entries.unshift(result);openDetail(result.dex,true);}else if(result.candidates.length){const finish=i=>saveScan(result,i,result.candidates[i].teraType,token);if(result.candidates.length===1&&result.candidates[0].certainty==='high'){const c=result.candidates[0];if(c.transformation==='terastal'&&!c.teraType)chooseTera(t=>saveScan(result,0,t,token));else await finish(0);}else choose('¿Cuál estás viendo?',result.candidates.map((c,i)=>({label:D.display(c.slug),run:()=>c.transformation==='terastal'&&!c.teraType?chooseTera(t=>saveScan(result,i,t,token)):finish(i)})));}else toast('No pude identificar un Pokémon.');}catch(err){if(err.name!=='AbortError'){if(!err.job)pendingScan=null;sheet('Escaneo',note(err.message),pendingScan?primary('Consultar resultado','resume-scan'):'');}}finally{scanBusy=false;}}
async function analyze(image){if(pendingScan){sheet('Análisis pendiente',note('Puedes recuperar el resultado anterior sin volver a enviar la imagen.'),primary('Consultar resultado','resume-scan'));return;}if(scanBusy)return;scanBusy=true;lastScan=Date.now();const token=epoch;clearTimeout(scanTimer);$('.reticle')?.classList.add('scanning');cameraStatus('Analizando imagen…');toast('Identificando Pokémon…');controller=new AbortController();try{await refresh(false);const result=await scanJob('recognize',{image},controller.signal);if(token!==epoch||document.hidden)return;scanBusy=false;$('.reticle')?.classList.remove('scanning');if(!result.candidates.length){cameraStatus('No identificado · prueba otro ángulo');toast('No pude identificar un Pokémon con claridad.');return;}const finish=index=>{const c=result.candidates[index];if(c.transformation==='terastal'&&!c.teraType)chooseTera(t=>saveScan(result,index,t,token));else return saveScan(result,index,c.teraType,token);};if(result.candidates.length===1&&result.candidates[0].certainty==='high')await finish(0);else choose('¿Cuál estás viendo?',[...result.candidates.map((c,i)=>({label:D.display(c.slug)+(c.transformation==='terastal'?' · Teracristalizado':c.transformation==='dynamax'?' · Dinamax':'')+' · #'+c.id,run:()=>finish(i)})),{label:'Ninguno / buscar por nombre',run:()=>go({page:'home'})}]);}catch(e){if(e.name!=='AbortError'&&token===epoch){cameraStatus(e.message);toast(e.message);if(pendingScan)sheet('Análisis pendiente',note(e.message),primary('Consultar resultado','resume-scan'));}}finally{if(token===epoch){scanBusy=false;$('.reticle')?.classList.remove('scanning');}}}
async function saveScan(result,index,teraType,token){if(token!==epoch||document.hidden)return;const entry=await scanJob('encounters',{ticket:result.ticket,candidate:index,teraType,id:D.encounterId()},controller?.signal);if(token!==epoch||document.hidden)return;entries.unshift(entry);await cached('get:/api/bootstrap',{settings,encounters:entries,csrf});if(token!==epoch||document.hidden)return;openDetail(entry.dex,true);}
async function deleteEntry(identity){const entry=entries.find(e=>e.id===identity);if(!entry)return;const token=epoch;const el=sheet('Eliminar registro',`<p class="center">${E(entry.dex.name)} · ${E(date(entry.at))}</p>${note('Se elimina únicamente este encuentro.')}`,primary('Eliminar','confirm-delete','trash'));on('[data-action="confirm-delete"]','click',async(_,b)=>{b.disabled=true;await api('/api/encounters/'+identity,undefined,{method:'DELETE'});entries=entries.filter(e=>e.id!==identity);await cached('get:/api/bootstrap',{settings,encounters:entries,csrf});if(token===epoch){closeSheet();rerender();toast('Registro eliminado.');}},el);}
function encounterOptions(identity){const entry=entries.find(e=>e.id===identity);if(!entry)return;choose(entry.dex.name,[{label:'Ver ficha',run:()=>openDetail(entry.dex)},{label:'Corregir Pokémon o forma',run:()=>correctEntry(identity)},{label:'Cambiar formato',run:()=>choose('Formato',['peluche','figura','carta','videojuego','imagen','otro'].map(media=>({label:D.display(media),run:async()=>{await api('/api/encounters/'+identity,{media});await refresh();rerender();}})))},{label:'Eliminar registro',run:()=>deleteEntry(identity)}]);}
function correctEntry(identity){const el=sheet('Corregir Pokémon',`<form id="correct-form" class="sheet-fields"><input class="field" id="correct-query" placeholder="Nombre, número o forma" aria-label="Nombre, número o forma" required><button type="submit" class="primary-btn">Corregir</button></form>`);const token=epoch;on('#correct-form','submit',async e=>{e.preventDefault();const query=$('#correct-query').value;await api('/api/encounters/'+identity,{lookup:query,transformation:'none'});await refresh();if(token===epoch){closeSheet();rerender();toast('Registro corregido; conserva la fecha.');}},el);}
function passwordSheet(){const el=sheet('Cambiar contraseña',`<form id="password-form" class="sheet-fields"><input class="field" id="current-password" type="password" autocomplete="current-password" aria-label="Contraseña actual" placeholder="Contraseña actual" required><input class="field" id="new-password" type="password" autocomplete="new-password" aria-label="Nueva contraseña" placeholder="Nueva contraseña" minlength="12" required><button type="submit" class="primary-btn">Guardar contraseña</button></form>`);on('#password-form','submit',async e=>{e.preventDefault();await api('/api/password',{current:$('#current-password').value,password:$('#new-password').value});closeSheet();toast('Contraseña cambiada.');},el);}
async function dispatch(action,el){const [command,...parts]=action.split(':'),arg=parts.join(':');switch(command){case 'nav':{const token=epoch;if(arg==='collection'||arg==='stats')await refresh();if(token===epoch)go({page:arg});break;}case 'back':back();break;case 'camera':await openCamera();break;case 'photo':chooseImage(true);break;case 'capture':await audio.unlock().catch(e=>toast(e.message));await capture();break;case 'gallery':await chooseImage();break;case 'history':go({page:'history'});break;case 'history-species':go({page:'history',species:view.dex.id});break;case 'entry':{const e=entries.find(e=>e.id===arg);if(e)openDetail(e.dex);break;}case 'learner':{const e=view.ready.find(e=>e.id===arg);if(e&&entries.some(v=>D.slug(v.dex)===D.slug(e.dex)))openDetail(e.dex);break;}case 'type':go({page:'collection',type:arg,query:''});break;case 'species':go({page:'history',species:Number(arg)});break;case 'stats':view.mode=arg;rerender();break;case 'tab':view.tab=arg;audio.stop();rerender();break;case 'statmode':view.statMode=arg;rerender();break;case 'method':view.method=arg;view.sort=arg==='level-up'?'level':'display';rerender();break;case 'sort':view.desc=view.sort===arg?!view.desc:false;view.sort=arg;$('#move-rows').innerHTML=moveTableRows();break;case 'voice':await speak(view.dex);break;case 'cry':{await audio.unlock();audio.stop();const token=audio.generation,bytes=await api('/api/asset?url='+encodeURIComponent(view.dex.cry),undefined,{binary:true});try{await audio.play(bytes,false,1,token);}catch{toast('Safari no pudo reproducir este sonido. La narración sigue disponible.');}break;}case 'register':confirmRegister();break;case 'favorite':{const id=view.dex.id;settings.favorites=(settings.favorites||[]).includes(id)?settings.favorites.filter(v=>v!==id):[...(settings.favorites||[]),id];settings=await api('/api/settings',{favorites:settings.favorites});toast(settings.favorites.includes(id)?'Añadido a favoritos.':'Favorito eliminado.');break;}case 'evolution':{const d=entries.find(e=>e.species===Number(arg))?.dex;if(d)openDetail(d);break;}case 'form':{const d=view.forms[Number(arg)];if(d&&!d.unseen&&D.owned(entries,d))openDetail(d);break;}case 'retry-wiki':wikiCache.delete(view.dex.name);loadWiki(view.dex);break;case 'detail-options':choose(view.dex.name,[{label:'Registrar encuentro',run:()=>confirmRegister()},{label:'Elegir forma del encuentro',run:()=>chooseForm(view.dex)},{label:'Ver registros',run:()=>go({page:'history',species:view.dex.id})},{label:'Escanear otro Pokémon',run:openCamera}]);break;case 'move':showMove(arg);break;case 'learners':await showLearners();break;case 'back-move':{const origin=view.origin;go(origin);setTimeout(()=>showMove(origin.lastMove),0);break;}case 'retry-learners':{const origin=view.origin;view=origin;await showLearners();break;}case 'close-sheet':closeSheet();break;case 'encounter-options':encounterOptions(arg);break;case 'delete':await deleteEntry(arg);break;case 'export':await exportFile();break;case 'import':$('#import-file').click();break;case 'check-recognition':{el.disabled=true;try{await saveSettings(undefined,true);toast('Consultando el servicio…');const result=await api('/api/check-recognition',{});const q=result.daily;if(result.provider==='chatgpt'){await refresh(false);rerender();}sheet('Reconocimiento · '+({chatgpt:'ChatGPT',openrouter:'OpenRouter',gemini:'Gemini'}[result.provider]),(q?card('Hoy',pair('Usadas',q.used)+pair('Límite diario',q.limit)+pair('Restantes',q.remaining)):'')+note(result.message)+note('Pokédex no añade un tope diario de análisis. Esta consulta no envía fotos ni genera un reconocimiento.'));}finally{if(el.isConnected)el.disabled=false;}break;}case 'chatgpt-setup':chatgptSetup();break;case 'chatgpt-import':if(!window.isSecureContext||location.protocol!=='https:')throw Error('Abre Pokédex mediante HTTPS de confianza para conectar ChatGPT.');$('#chatgpt-file').click();break;case 'chatgpt-models':settings=await api('/api/chatgpt/models',{});rerender();break;case 'chatgpt-disconnect':choose('Desconectar ChatGPT',[{label:'Desconectar en esta Pokédex',run:async()=>{settings=await api('/api/chatgpt/disconnect',{});rerender();toast('Conexión local eliminada. Puedes revocar el permiso también en los ajustes de ChatGPT.');}}]);break;case 'resume-scan':await resumeScan();break;case 'connection':await checkConnection();break;case 'check-voice':{await saveSettings();const result=await api('/api/check-access',{});sheet('Resultado de Gemini',`<p>${E(result.message)}</p>`);break;}case 'test-voice':{el.disabled=true;try{toast('Activando audio…');await audio.unlock();await saveSettings(undefined,true);const d=entries[0]?.dex||await api('/api/dex?q=pikachu');await speak(d,true);}finally{if(el.isConnected)el.disabled=false;}break;}case 'password':passwordSheet();break;case 'clear-keys':choose('Eliminar claves',[{label:'Eliminar claves de reconocimiento y voz',run:async()=>{settings=await api('/api/settings',{clear_gemini_key:true,clear_openrouter_key:true,clear_voice_key:true});rerender();toast('Claves eliminadas.');}}]);break;case 'logout':await api('/api/logout',{});await clearCache();entries=[];settings={};csrf='';historyViews.length=0;historyIndex=-1;moveCache.clear();wikiCache.clear();go({page:'login'},true);break;case 'install-help':sheet('Pokédex en tu iPhone',`<p>En Safari, toca Compartir → Añadir a pantalla de inicio. Activa «Abrir como app web» si aparece.</p>${note('En HTTP puedes escanear tomando una foto. HTTPS permite cámara en vivo y lectura sin conexión. Al tocar el escáner o Voz habilitas el audio para esta sesión.')}`);break;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;if(['confirm-register','choose-form','confirm-delete'].includes(action))return;e.preventDefault();Promise.resolve(dispatch(action,el)).catch(err=>toast(err.message));});
window.addEventListener('online',()=>refresh(false).then(()=>{offline=false;showOffline();if(view.page!=='camera')rerender();}).catch(()=>{}));
async function boot(){if('serviceWorker'in navigator&&window.isSecureContext)navigator.serviceWorker.register('/sw.js').catch(()=>{});try{[catalog,chart]=await Promise.all([request('/assets/game-catalog.json').then(r=>r.data),request('/assets/type-chart.json').then(r=>r.data)]);await refresh();go({page:'home'},true);if('serviceWorker'in navigator&&window.isSecureContext)navigator.serviceWorker.register('/sw.js').catch(()=>{});}catch(err){if(err.status===401){go({page:'login'},true);if('serviceWorker'in navigator&&window.isSecureContext)navigator.serviceWorker.register('/sw.js').catch(()=>{});}else{app.innerHTML=`<main class="login"><img class="login-logo" src="/assets/icon.svg" alt=""><h1>Pokédex</h1><p class="error-text">${E(err.message)}</p><button class="primary-btn" id="retry-start">Reintentar</button></main>`;on('#retry-start','click',boot);}}}
window.addEventListener('pageshow',event=>{if(event.persisted&&view.page!=='login')refresh(false).then(()=>{if(view.page!=='camera')rerender();}).catch(e=>toast(e.message));});
boot();
